//! `contract/status-fixtures/`: the documents Mooring.app's Codable mirror
//! is tested against (design §15). They are generated by the scenarios
//! and pinned byte for byte, and each decodes and re-encodes to exactly
//! its bytes. Beside them, `variants.json` holds one value of every
//! variant of every enum a status carries; the crate's own tests generate
//! and pin it (`src/tests/variants.rs`).
//!
//! To change one, change the scenario or the types, write the scenario's
//! encoding ([`encode`]) over the file, and review the diff.

use std::collections::BTreeSet;
use std::fs;
use std::path::Path;

use mooring_daemon_core::MacStatusV1;

use crate::scenarios;
use crate::support::GRAMMAR_SHAPED_LABEL;

const FIXTURES: &[(&str, &[u8])] = &[
    (
        "serving",
        include_bytes!("../../../../contract/status-fixtures/serving.json"),
    ),
    (
        "degraded",
        include_bytes!("../../../../contract/status-fixtures/degraded.json"),
    ),
    (
        "down",
        include_bytes!("../../../../contract/status-fixtures/down.json"),
    ),
];

/// A fixture file's content: the pretty-printed document and a newline.
fn encode(status: &MacStatusV1) -> String {
    let mut text = serde_json::to_string_pretty(status).unwrap();
    text.push('\n');
    text
}

#[test]
fn the_fixtures_are_what_the_scenarios_generate() {
    let scenarios = scenarios::all();
    assert_eq!(
        scenarios.iter().map(|(name, _)| *name).collect::<Vec<_>>(),
        FIXTURES.iter().map(|(name, _)| *name).collect::<Vec<_>>()
    );
    for ((name, status), (_, bytes)) in scenarios.iter().zip(FIXTURES) {
        assert!(
            encode(status).as_bytes() == *bytes,
            "contract/status-fixtures/{name}.json is not what its scenario generates"
        );
    }
}

#[test]
fn every_fixture_round_trips_byte_for_byte() {
    for (name, bytes) in FIXTURES {
        let status: MacStatusV1 = serde_json::from_slice(bytes)
            .unwrap_or_else(|error| panic!("{name}.json does not decode: {error}"));
        assert!(
            encode(&status).as_bytes() == *bytes,
            "{name}.json does not re-encode to itself"
        );
        // The stream carries the same document as one compact line.
        let line = serde_json::to_string(&status).unwrap();
        assert!(!line.contains('\n'));
        assert_eq!(serde_json::from_str::<MacStatusV1>(&line).unwrap(), status);
    }
}

/// The directory holds exactly the scenario fixtures, the variants
/// document and their licence sidecars, so a stale or stray document
/// cannot reach the app's tests.
#[test]
fn the_fixture_directory_holds_exactly_the_scenarios() {
    let directory = Path::new(env!("CARGO_MANIFEST_DIR")).join("../../contract/status-fixtures");
    let found: BTreeSet<String> = fs::read_dir(&directory)
        .unwrap()
        .map(|entry| entry.unwrap().file_name().into_string().unwrap())
        .collect();
    let names: Vec<&str> = FIXTURES
        .iter()
        .map(|(name, _)| *name)
        .chain(["variants"])
        .collect();
    let expected: BTreeSet<String> = names
        .iter()
        .flat_map(|name| [format!("{name}.json"), format!("{name}.json.license")])
        .collect();
    assert_eq!(found, expected);
    for name in &names {
        let sidecar = fs::read_to_string(directory.join(format!("{name}.json.license"))).unwrap();
        assert_eq!(sidecar, "SPDX-License-Identifier: GPL-3.0-or-later\n");
    }
}

/// The documents name users by opaque id and alias only: no fixture user's
/// label, nor the label the degraded scenario gives a user, appears in any
/// of them.
#[test]
fn the_fixtures_carry_no_user_labels() {
    let mut labels = vec![GRAMMAR_SHAPED_LABEL.to_owned()];
    for fixture in mooring_fixtures::all().unwrap() {
        labels.extend(
            fixture
                .deployment
                .users()
                .values()
                .map(|user| user.label.as_str().to_owned()),
        );
    }
    assert!(!labels.is_empty());
    for (name, bytes) in FIXTURES {
        let text = std::str::from_utf8(bytes).unwrap();
        for label in &labels {
            assert!(!text.contains(label.as_str()), "{name}.json names {label}");
        }
        assert!(!text.contains("\"label\""), "{name}.json has a label field");
    }
}
